import org.openrndr.math.Vector2
import org.openrndr.shape.*
import kotlin.math.abs
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

class RemoveSelfIntersectionsStarOffsetTest {

    /**
     * An outward offset of a 5-point star, with small swallowtail loops at its concave corners.
     * The arcs that connect the outline to a loop are only ~0.013 long, so the inside/outside
     * probes `nonZeroSelfUnion()` uses to classify them sit ~1e-5 from the curve. The old
     * winding number found ray crossings through `Intersections.lineCurve`, whose parametric
     * rounding is relative to the ray's length, so a crossing that close to the probe was
     * rounded onto the probe and dropped. Both probes then looked "inside", the connecting arcs
     * were discarded, the outline could no longer close into a ring, and NON_ZERO returned zero
     * contours.
     */
    @Test
    fun testNonZeroOnStarOffsetWithSwallowtails() {
        val evenOdd = starOffset.shape.removeSelfIntersections(FillRule.EVEN_ODD)
        assertEquals(6, evenOdd.contours.size)

        for (contour in listOf(starOffset, starOffset.reversed)) {
            val nonZero = contour.shape.removeSelfIntersections(FillRule.NON_ZERO)
            assertEquals(1, nonZero.contours.size)
            assertTrue(!nonZero.contours[0].isSelfIntersecting)
            assertTrue(abs(nonZero.area - abs(starOffset.shape.area)) < 5.0)
        }
    }

    /**
     * An inward offset of a 5-point star that pinches apart into six pieces. At each star tip the
     * offset makes a U-turn tighter than the intersection precision, whose legs cross again
     * ~0.009 from the turn: a loop only ~2e-5 wide. Those used to resolve into ten sliver rings
     * (area ~1e-7, one of them self-intersecting) next to the six real pieces, and the imprecise
     * crossings they were cut off at made mirror-image pieces differ in area by up to 1e-3.
     * The loops are now cut off at their (refined) crossings before resolving.
     */
    @Test
    fun testStarInwardOffsetHasNoSlivers() {
        for (fillRule in FillRule.entries) {
            val resolved = starInwardOffset.shape.removeSelfIntersections(fillRule)
            assertEquals(6, resolved.contours.size)
            for (contour in resolved.contours) {
                assertTrue(!contour.isSelfIntersecting)
                assertTrue(contour.shape.area > 1000.0)
            }

            // the star is mirror-symmetric, so the four off-axis pieces come in equal-area pairs
            val areas = resolved.contours.map { it.shape.area }.sorted()
            assertTrue(abs(areas[0] - areas[1]) < 1e-5)
            assertTrue(abs(areas[3] - areas[4]) < 1e-5)
        }
    }
}

